const std = @import("std");

pub fn main(init: std.process.Init) !void {
    var in_buf: [256]u8 = undefined;
    var stdin = std.Io.File.reader(.stdin(), init.io, &in_buf);
    var out_buf: [1024]u8 = undefined;
    var stdout = std.Io.File.writer(.stdout(), init.io, &out_buf);
    const out = &stdout.interface;

    const line = (stdin.interface.takeDelimiter('\n') catch null) orelse "";
    try out.print("Hello from Flux\n", .{});
    try out.print("You typed: {s}\n", .{std.mem.trim(u8, line, " \r")});
    try out.flush();
}

